R,C=len(g),len(g[0])
seen=set(); comps=[]
for i in range(R):
 for j in range(C):
  if g[i][j]==3 and (i,j) not in seen:
   stack=[(i,j)]; seen.add((i,j)); comp=[]
   while stack:
    x,y=stack.pop(); comp.append((x,y))
    for dx,dy in ((1,0),(-1,0),(0,1),(0,-1)):
     q=(x+dx,y+dy)
     if 0<=q[0]<R and 0<=q[1]<C and g[q[0]][q[1]]==3 and q not in seen:
      seen.add(q); stack.append(q)
   comps.append(comp)
[(len(c),(min(x for x,y in c),max(x for x,y in c),min(y for x,y in c),max(y for x,y in c))) for c in comps]

